"""Operaciones reproducibles sin credenciales incrustadas."""
COMPANY='mutation($input:CreateCompanyInput!){createCompany(input:$input){id name isActive}}'
ADMIN='mutation($input:CreateCompanyAdminInput!){createCompanyAdmin(input:$input){id userId companyId isAdmin user{id email}}}'
USER='mutation($input:CreateCompanyUserInput!){createCompanyUser(input:$input){id userId isAdmin}}'
LOGIN='mutation($input:LoginInput!){login(input:$input){token tokenType user{id email}}}'
ROLES='query{roles{id code name description isActive} permissions{id code name description isActive}}'
MATRIX='query($role:ID!){rolePermissions(roleId:$role){id isActive role{code} permission{id code isActive}}}'
ASSIGN_ROLE='mutation($input:AssignRoleInput!){assignRole(input:$input){id isActive role{id code} companyUser{id companyId isAdmin}}}'
ADD_PERMISSION='mutation($input:AssignPermissionToRoleInput!){assignPermissionToRole(input:$input){id isActive role{code} permission{code}}}'
REMOVE_PERMISSION='mutation($role:ID!,$permission:ID!){removePermissionFromRole(roleId:$role,permissionId:$permission)}'
ACCOUNT='mutation($input:CreateAccountInput!){createAccount(input:$input){id companyId name accountType bankName accountNumber clabe cardLastDigits shortDescription longDescription isActive createdAt updatedAt company{id}}}'
CONCEPT='mutation($input:CreateConceptInput!){createConcept(input:$input){id companyId name conceptType shortDescription longDescription isActive createdAt updatedAt}}'
LINK='mutation($input:AssignConceptToAccountInput!){assignConceptToAccount(input:$input){id isActive createdAt account{id} concept{id}}}'
REMOVE_LINK='mutation($a:ID!,$c:ID!){removeConceptFromAccount(accountId:$a,conceptId:$c)}'
TX='mutation($input:CreateTransactionInput!){createTransaction(input:$input){id amount transactionType transactionDate capturedAt capturedBy isActive account{id} concept{id} capturedByUser{id}}}'
TXS='query($a:ID,$type:TransactionType,$limit:Int,$offset:Int){transactions(accountId:$a,transactionType:$type,limit:$limit,offset:$offset){id amount isActive capturedBy}}'
DELETE='mutation($id:ID!){deleteTransaction(id:$id){id isActive amount}}'
BALANCE='query($a:ID!){accountBalance(accountId:$a)}'
CREATE_ROLE='mutation($input:CreateRoleInput!){createRole(input:$input){id code name description isActive}}'
CREATE_PERMISSION='mutation($input:CreatePermissionInput!){createPermission(input:$input){id code name description isActive}}'
DEACTIVATE_ROLE='mutation($id:ID!){deactivateRole(id:$id){id isActive}}'
MEMBERS='query($id:ID!){companyUsers(companyId:$id){id isAdmin isActive user{id}}}'
ACCOUNTS='query($id:ID!,$type:AccountType,$active:Boolean){accounts(companyId:$id,accountType:$type,activeOnly:$active){id name isActive}}'
CONCEPTS='query($id:ID!,$type:ConceptType,$active:Boolean){concepts(companyId:$id,conceptType:$type,activeOnly:$active){id name isActive}}'
